// TestRustGoalTypesInSyncWithSchema is the goal-type parity guarantee: the
// committed Rust IntentGoalType enum (with its as_str, from_wire and ALL) must
// match the vendored goal-vocabulary.json (the node's goal set, generated by
// infrix-core), and the pinned PUBLISHED infrix-schema must not declare a goal
// that vocabulary lacks. A goal added to the node without regenerating this crate
// (run `go run .` in this dir) fails here.
//
// It used to compare the enum to the pinned published schema alone, which lagged
// the node: the check passed while the enum was fourteen goals short.
func TestRustGoalTypesInSyncWithSchema(t *testing.T) {
	changed, err := generate(repoRoot(), true)
	if err != nil {
		t.Fatalf("sdkgen check: %v", err)
	}
	if len(changed) > 0 {
		t.Errorf("Rust goal-type enum is stale vs goal-vocabulary.json; regenerate with `go run .`: %v", changed)
	}
}

// scratchRepo copies the files sdkgen reads into a temp repo root, so a planted
// defect never touches the real tree.
func scratchRepo(t *testing.T) string {
	t.Helper()
	dst := t.TempDir()
	rels := []string{vocabularyRel}
	for _, tg := range allTargets() {
		rels = append(rels, tg.RelPath)
	}
	for _, rel := range rels {
		raw, err := os.ReadFile(filepath.Join(repoRoot(), rel))
		if err != nil {
			t.Fatalf("copy %s: %v", rel, err)
		}
		out := filepath.Join(dst, rel)
		if err := os.MkdirAll(filepath.Dir(out), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(out, raw, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	return dst
}

func rewrite(t *testing.T, root, rel string, edit func(string) string) {
	t.Helper()
	full := filepath.Join(root, rel)
	raw, err := os.ReadFile(full)
	if err != nil {
		t.Fatal(err)
	}
	before := string(raw)
	after := edit(before)
	if after == before {
		t.Fatalf("the planted edit to %s changed nothing, so the test below would prove nothing", rel)
	}
	if err := os.WriteFile(full, []byte(after), 0o644); err != nil {
		t.Fatal(err)
	}
}

var rustRel = filepath.Join("infrix-types", "src", "governance.rs")

// TestUnmodifiedScratchRepoIsInSync anchors the planted-defect tests: if the
// untouched copy were already out of sync, "the check failed" would prove nothing.
func TestUnmodifiedScratchRepoIsInSync(t *testing.T) {
	changed, err := generate(scratchRepo(t), true)
	if err != nil {
		t.Fatalf("an unmodified copy fails the check: %v", err)
	}
	if len(changed) > 0 {
		t.Fatalf("an unmodified copy is reported stale: %v", changed)
	}
}

// TestCheckDetectsAnEnumMissingAGoal plants the defect the SDK actually had: the
// enum lacked goals the vocabulary has (EVM_CALL among them).
func TestCheckDetectsAnEnumMissingAGoal(t *testing.T) {
	root := scratchRepo(t)
	rewrite(t, root, rustRel, func(s string) string {
		var kept []string
		for _, line := range strings.SplitAfter(s, "\n") {
			if strings.Contains(line, "EvmCall") || strings.Contains(line, `"EVM_CALL"`) {
				continue
			}
			kept = append(kept, line)
		}
		return strings.Join(kept, "")
	})
	changed, err := generate(root, true)
	if err != nil {
		t.Fatalf("generate: %v", err)
	}
	if len(changed) != 1 {
		t.Fatalf("an enum missing EVM_CALL was reported as %v; the rust target must be stale", changed)
	}
}

// TestCheckDetectsADriftedWireString plants a wire string that no longer matches
// its variant (the enum compiles either way).
func TestCheckDetectsADriftedWireString(t *testing.T) {
	root := scratchRepo(t)
	rewrite(t, root, rustRel, func(s string) string {
		return strings.Replace(s, `IntentGoalType::MoveExec => "MOVE_EXEC"`, `IntentGoalType::MoveExec => "MOVE_EXECUTE"`, 1)
	})
	changed, err := generate(root, true)
	if err != nil {
		t.Fatalf("generate: %v", err)
	}
	if len(changed) != 1 {
		t.Fatalf("a drifted wire string was reported as %v; the rust target must be stale", changed)
	}
}

// TestFloorRejectsAVocabularyBehindThePublishedSchema is the guard that replaces
// "the pinned schema is the source": a vendored vocabulary that lacks a goal the
// pinned published schema declares fails, naming the goal.
func TestFloorRejectsAVocabularyBehindThePublishedSchema(t *testing.T) {
	root := scratchRepo(t)
	rewrite(t, root, vocabularyRel, func(s string) string {
		var kept []string
		for _, line := range strings.SplitAfter(s, "\n") {
			if strings.Contains(line, `"goal":"SESSION_KEY_DELEGATE"`) {
				continue
			}
			kept = append(kept, line)
		}
		out := strings.Join(kept, "")
		// Keep count consistent with the list so the floor, not the count check, is what fires.
		return strings.Replace(out, `"count": 81`, `"count": 80`, 1)
	})
	_, err := generate(root, true)
	if err == nil {
		t.Fatal("a vocabulary lacking a goal the pinned published schema declares was accepted")
	}
	if !strings.Contains(err.Error(), "SESSION_KEY_DELEGATE") {
		t.Fatalf("the floor failure does not name the missing goal: %v", err)
	}
}

func TestLoadVocabularyRefusesMalformedInput(t *testing.T) {
	cases := map[string]string{
		"empty":       `{"count":0,"goals":[]}`,
		"count wrong": `{"count":2,"goals":[{"goal":"A_B"}]}`,
		"duplicate":   `{"count":2,"goals":[{"goal":"A_B"},{"goal":"A_B"}]}`,
		"lower case":  `{"count":1,"goals":[{"goal":"a_b"}]}`,
		"injection":   `{"count":1,"goals":[{"goal":"A\"; drop"}]}`,
		"not json":    `not json`,
		"double _":    `{"count":1,"goals":[{"goal":"A__B"}]}`,
	}
	for name, body := range cases {
		root := t.TempDir()
		if err := os.WriteFile(filepath.Join(root, vocabularyRel), []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
		if _, err := loadVocabulary(root); err == nil {
			t.Errorf("%s: a malformed vocabulary was accepted", name)
		}
	}
	if _, err := loadVocabulary(t.TempDir()); err == nil {
		t.Error("a missing vocabulary file was accepted")
	}
}

func TestPascalCase(t *testing.T) {
	for wire, want := range map[string]string{
		"CONVERT":              "Convert",
		"EVM_CALL":             "EvmCall",
		"SVM_EXEC":             "SvmExec",
		"EBPF_EXEC":            "EbpfExec",
		"COSMWASM_EXEC":        "CosmwasmExec",
		"SESSION_KEY_DELEGATE": "SessionKeyDelegate",
	} {
		if got := pascalCase(wire); got != want {
			t.Errorf("pascalCase(%q) = %q, want %q", wire, got, want)
		}
	}
}
